sealed interface Value {
    data class Integer(val value: Long) : Value
    data class BooleanValue(val value: Boolean) : Value
    data class StringValue(val value: String) : Value
    data class PairValue(val first: Value, val second: Value) : Value
    data class ListValue(val values: List<Value>) : Value
    data class Closure(val parameter: Parameter, val body: Expr, val environment: Map<String, Value>) : Value
    data class Builtin(val name: String) : Value
}
typealias ValueEnvironment = Map<String, Value>
class RuntimeError(val position: Position, val reason: String) : Exception(reason)
fun checkedInteger(value: Long, position: Position): Value {
    if (value !in -2147483648L..2147483647L) throw RuntimeError(position, "integer overflow"); return Value.Integer(value)
}
fun compareValues(a: Value, b: Value, position: Position): Int = when {
    a is Value.Integer && b is Value.Integer -> a.value.compareTo(b.value)
    a is Value.BooleanValue && b is Value.BooleanValue -> a.value.compareTo(b.value)
    a is Value.StringValue && b is Value.StringValue -> a.value.compareTo(b.value)
    a is Value.PairValue && b is Value.PairValue -> {
        val first = compareValues(a.first, b.first, position); if (first == 0) compareValues(a.second, b.second, position) else first
    }
    a is Value.ListValue && b is Value.ListValue -> {
        var order = 0; for ((x, y) in a.values.zip(b.values)) {
            order = compareValues(x, y, position); if (order != 0) break
        }; if (order != 0) order else a.values.size.compareTo(b.values.size)
    }
    else -> throw RuntimeError(position, "functional value compared")
}
fun matchPattern(pattern: Pattern, value: Value, bindings: MutableMap<String, Value>): Boolean = when (pattern) {
    is WildPattern -> true
    is NamePattern -> {
        bindings[pattern.name] = value; true
    }
    is IntPattern -> value is Value.Integer && pattern.value == value.value
    is BoolPattern -> value is Value.BooleanValue && pattern.value == value.value
    is StringPattern -> value is Value.StringValue && pattern.value == value.value
    is ConsPattern -> value is Value.ListValue && value.values.isNotEmpty() && matchPattern(pattern.head, value.values[0], bindings) && matchPattern(pattern.tail, Value.ListValue(value.values.drop(1)), bindings)
    is ListPattern -> value is Value.ListValue && pattern.elements.size == value.values.size && pattern.elements.zip(value.values).all {
        (p, v) -> matchPattern(p, v, bindings)
    }
    is PairPattern -> value is Value.PairValue && matchPattern(pattern.first, value.first, bindings) && matchPattern(pattern.second, value.second, bindings)
}
class Evaluator {
    var calls = 0
    fun group(group: Group, environment: ValueEnvironment): Pair<ValueEnvironment, List<Value>> {
        if (group.recursive != null) {
            val shared = environment.toMutableMap(); val values = group.bindings.map {
                binding -> val function = binding.expression as Lambda; Value.Closure(function.parameter, function.body, shared)
            }
            for ((binding, value) in group.bindings.zip(values)) shared[binding.name] = value
            return Pair(shared.toMap(), values)
        }
        val values = group.bindings.map {
            expression(it.expression, environment)
        }; val result = environment.toMutableMap(); for ((binding, value) in group.bindings.zip(values)) result[binding.name] = value
        return Pair(result, values)
    }
    fun apply(function: Value, argument: Value, position: Position): Value {
        calls++
        return when (function) {
            is Value.Closure -> {
                val inner = function.environment.toMutableMap(); function.parameter.name?.let {
                    inner[it] = argument
                }; expression(function.body, inner)
            }; is Value.Builtin -> applyBuiltin(function.name, argument, position); else -> error("not a function")
        }
    }
    fun expression(e: Expr, environment: ValueEnvironment): Value = when (e) {
        is IntExpr -> Value.Integer(e.value)
        is BoolExpr -> Value.BooleanValue(e.value)
        is StringExpr -> Value.StringValue(e.value)
        is NameExpr -> environment.getValue(e.name)
        is Lambda -> Value.Closure(e.parameter, e.body, environment.toMap())
        is Apply -> {
            val function = expression(e.function, environment); val argument = expression(e.argument, environment); apply(function, argument, e.position)
        }
        is Negate -> checkedInteger(-(expression(e.operand, environment) as Value.Integer).value, e.position)
        is Binary -> {
            val left = expression(e.left, environment)
            if (e.op == "&&") {
                if ((left as Value.BooleanValue).value) expression(e.right, environment) else Value.BooleanValue(false)
            }
            else if (e.op == "||") {
                if ((left as Value.BooleanValue).value) Value.BooleanValue(true) else expression(e.right, environment)
            }
            else {
                val right = expression(e.right, environment)
                when (e.op) {
                    "+", "-", "*", "/", "mod" -> {
                        val a = (left as Value.Integer).value; val b = (right as Value.Integer).value; if (e.op in listOf("/", "mod") && b == 0L) throw RuntimeError(e.operatorPosition, "division by zero"); val value = when (e.op) {
                            "+" -> a + b; "-" -> a - b; "*" -> a * b; "/" -> a / b; else -> a - b * (a / b)
                        }; checkedInteger(value, e.operatorPosition)
                    }
                    "^" -> Value.StringValue((left as Value.StringValue).value + (right as Value.StringValue).value)
                    "::" -> Value.ListValue(listOf(left) + (right as Value.ListValue).values)
                    else -> {
                        val order = compareValues(left, right, e.operatorPosition); Value.BooleanValue(when (e.op) {
                            "=" -> order == 0; "<>" -> order != 0; "<" -> order < 0; ">" -> order > 0; "<=" -> order <= 0; else -> order >= 0
                        })
                    }
                }
            }
        }
        is Conditional -> expression(if ((expression(e.condition, environment) as Value.BooleanValue).value) e.yes else e.no, environment)
        is PairExpr -> {
            val first = expression(e.first, environment); val second = expression(e.second, environment); Value.PairValue(first, second)
        }
        is ListExpr -> Value.ListValue(e.elements.map {
            expression(it, environment)
        })
        is Match -> {
            val matched = expression(e.value, environment); var result: Value? = null; for ((pattern, body) in e.arms) {
                val bindings = mutableMapOf<String, Value>(); if (matchPattern(pattern, matched, bindings)) {
                    result = expression(body, environment + bindings); break
                }
            }; result ?: throw RuntimeError(e.position, "match failure")
        }
        is LetIn -> {
            val (inner, _) = group(e.group, environment); expression(e.body, inner)
        }
    }
}

sealed interface TypeErrorKind {
    data class Message(val text: String) : TypeErrorKind
    data class Function(val type: MLType) : TypeErrorKind
    data class Check(val expected: MLType, val found: MLType, val failure: UnifyFailure) : TypeErrorKind
}
class TypeError(val position: Position, val kind: TypeErrorKind) : Exception()
data class Local(val name: String, val position: Position, val scheme: Scheme)
class Inference {
    val unifier = Unifier()
    val locals = mutableListOf<Local>()
    val matches = mutableMapOf<Position, Pair<MLType, List<Pattern>>>()
    fun clear() {
        locals.clear(); matches.clear()
    }
    fun message(position: Position, message: String): TypeError = TypeError(position, TypeErrorKind.Message(message))
    fun check(expected: MLType, found: MLType, position: Position) {
        try {
            unifier.unify(expected, found)
        } catch (failure: UnifyFailure) {
            throw TypeError(position, TypeErrorKind.Check(expected, found, failure))
        }
    }
    fun group(group: Group, environment: TypeEnvironment, local: Boolean): Pair<TypeEnvironment, List<Scheme>> {
        val names = mutableSetOf<String>()
        for (binding in group.bindings) {
            if (!names.add(binding.name)) throw message(binding.position, "variable '${binding.name}' is bound twice in this let")
            if (group.recursive != null && binding.expression !is Lambda) throw message(binding.position, "'${binding.name}' in let rec must be a function")
        }
        val recursive = environment.toMutableMap(); val types = mutableListOf<MLType>()
        if (group.recursive != null) {
            for (binding in group.bindings) {
                val type = unifier.fresh(); recursive[binding.name] = Scheme(type); types.add(type)
            }
            for ((i, binding) in group.bindings.withIndex()) {
                val found = expression(binding.expression, recursive); check(types[i], found, binding.position)
            }
        } else {
            for (binding in group.bindings) types.add(expression(binding.expression, environment))
        }
        val schemes = types.map {
            unifier.generalize(it, environment)
        }; val result = environment.toMutableMap()
        for ((binding, scheme) in group.bindings.zip(schemes)) {
            result[binding.name] = scheme; if (local) locals.add(Local(binding.name, binding.position, scheme))
        }
        return Pair(result, schemes)
    }
    fun expression(e: Expr, environment: TypeEnvironment): MLType = when (e) {
        is IntExpr -> MLType.IntType
        is BoolExpr -> MLType.BoolType
        is StringExpr -> MLType.StringType
        is NameExpr -> {
            val scheme = environment[e.name]
            if (scheme != null) unifier.instantiate(scheme)
            else {
                val candidate = environment.keys.map {
                    Pair(editDistance(e.name, it), it)
                }.filter {
                    it.first <= 2 && it.first < e.name.length
                }.minWithOrNull(compareBy<Pair<Int, String>> {
                    it.first
                }.thenBy {
                    it.second
                }); throw message(e.position, "unbound variable '${e.name}'" + (candidate?.let {
                    " (did you mean '${it.second}'?)"
                } ?: ""))
            }
        }
        is Lambda -> {
            val argument = unifier.fresh(); val inner = environment.toMutableMap(); e.parameter.name?.let {
                inner[it] = Scheme(argument)
            }; val result = expression(e.body, inner); MLType.Function(argument, result)
        }
        is Apply -> {
            val function = unifier.resolve(expression(e.function, environment)); val expected: MLType; val result: MLType
            when (function) {
                is MLType.Variable -> {
                    expected = unifier.fresh(); result = unifier.fresh(); unifier.bind(function.id, MLType.Function(expected, result))
                }; is MLType.Function -> {
                    expected = function.argument; result = function.result
                }; else -> throw TypeError(e.function.position, TypeErrorKind.Function(function))
            }
            val found = expression(e.argument, environment); check(expected, found, e.argument.position); result
        }
        is Binary -> {
            val a: MLType; val b: MLType; val result: MLType
            when (e.op) {
                "+", "-", "*", "/", "mod" -> {
                    a = MLType.IntType; b = a; result = a
                }; "^" -> {
                    a = MLType.StringType; b = a; result = a
                }; "&&", "||" -> {
                    a = MLType.BoolType; b = a; result = a
                }; "::" -> {
                    a = unifier.fresh(); b = MLType.ListType(a); result = b
                }; else -> {
                    a = unifier.fresh(); b = a; result = MLType.BoolType
                }
            }
            val first = expression(e.left, environment); check(a, first, e.left.position); val second = expression(e.right, environment); check(b, second, e.right.position); result
        }
        is Negate -> {
            val found = expression(e.operand, environment); check(MLType.IntType, found, e.operand.position); MLType.IntType
        }
        is Conditional -> {
            val found = expression(e.condition, environment); check(MLType.BoolType, found, e.condition.position); val a = expression(e.yes, environment); val b = expression(e.no, environment); check(a, b, e.no.position); a
        }
        is PairExpr -> {
            val first = expression(e.first, environment); val second = expression(e.second, environment); MLType.PairType(first, second)
        }
        is ListExpr -> {
            val type = unifier.fresh(); for (element in e.elements) {
                val found = expression(element, environment); check(type, found, element.position)
            }; MLType.ListType(type)
        }
        is Match -> {
            val type = expression(e.value, environment); val result = unifier.fresh()
            for ((pattern, body) in e.arms) {
                val bindings = mutableMapOf<String, MLType>(); val found = this.pattern(pattern, bindings); check(type, found, pattern.position); val inner = environment.toMutableMap(); bindings.forEach {
                    (name, type) -> inner[name] = Scheme(type)
                }; val bodyType = expression(body, inner); check(result, bodyType, body.position)
            }
            matches[e.position] = Pair(type, e.arms.map {
                it.first
            }); result
        }
        is LetIn -> {
            val (inner, _) = group(e.group, environment, true); expression(e.body, inner)
        }
    }
    fun pattern(p: Pattern, bindings: MutableMap<String, MLType>): MLType = when (p) {
        is WildPattern -> unifier.fresh()
        is NamePattern -> {
            if (p.name in bindings) throw message(p.position, "variable '${p.name}' is bound twice in this pattern"); val type = unifier.fresh(); bindings[p.name] = type; type
        }
        is IntPattern -> MLType.IntType
        is BoolPattern -> MLType.BoolType
        is StringPattern -> MLType.StringType
        is ConsPattern -> {
            val type = unifier.fresh(); val head = pattern(p.head, bindings); check(type, head, p.head.position); val tail = pattern(p.tail, bindings); val list = MLType.ListType(type); check(list, tail, p.tail.position); list
        }
        is ListPattern -> {
            val type = unifier.fresh(); for (element in p.elements) {
                val found = pattern(element, bindings); check(type, found, element.position)
            }; MLType.ListType(type)
        }
        is PairPattern -> {
            val first = pattern(p.first, bindings); val second = pattern(p.second, bindings); MLType.PairType(first, second)
        }
    }
}

data class Position(val file: Int, val line: Int, val column: Int) : Comparable<Position> {
    override fun compareTo(other: Position): Int = compareValuesBy(this, other, {
        it.file
    }, {
        it.line
    }, {
        it.column
    })
}
data class Token(val kind: String, val spelling: String, val value: String, val position: Position)
object Lexer {
    fun letter(c: Char): Boolean = c in 'A'..'Z' || c in 'a'..'z'
    fun digit(c: Char): Boolean = c in '0'..'9'
    fun lex(text: String, file: Int): List<Token> {
        val positions = mutableListOf<Position>(); var row = 1; var column = 1
        for (c in text) {
            positions.add(Position(file, row, column)); if (c == '\n') {
                row++; column = 1
            } else column++
        }
        positions.add(Position(file, row, column))
        val tokens = mutableListOf<Token>(); var i = 0
        while (i < text.length) {
            if (text[i] == ' ' || text[i] == '\n') {
                i++; continue
            }
            val start = i; val kind: String; var value = ""
            if (text.startsWith("(*", i)) {
                val end = text.indexOf("*)", i + 2)
                if (end >= 0) {
                    i = end + 2; continue
                }
                tokens.add(Token("invalid", text.substring(start), "unterminated comment", positions[start])); break
            } else if (digit(text[i])) {
                i++; while (i < text.length && digit(text[i])) i++
                val n = text.substring(start, i).trimStart('0').ifEmpty {
                    "0"
                }.toLongOrNull()
                if (n != null && n <= 2147483647L) {
                    kind = "integer"; value = n.toString()
                } else {
                    kind = "invalid"; value = "integer literal too large"
                }
            } else if (letter(text[i]) || text[i] == '_') {
                i++; while (i < text.length && (letter(text[i]) || digit(text[i]) || text[i] in "_'")) i++
                value = text.substring(start, i); kind = if (value in listOf("let", "rec", "and", "in", "fun", "if", "then", "else", "match", "with", "true", "false", "mod", "val")) "keyword" else "identifier"
            } else if (text[i].code == 39 && i + 1 < text.length && text[i + 1] in 'a'..'z') {
                i += 2; while (i < text.length && (letter(text[i]) || digit(text[i]) || text[i] == '_')) i++
                kind = "type_variable"; value = text.substring(start, i)
            } else if (text[i] == '"') {
                i++; var closed = false; var valid = true; val decoded = StringBuilder()
                while (i < text.length && text[i] != '\n') {
                    if (text[i] == '"') {
                        i++; closed = true; break
                    }
                    if (text[i] == '\\' && i + 1 < text.length && text[i + 1] != '\n') {
                        when (text[i + 1]) {
                            'n' -> decoded.append('\n'); 't' -> decoded.append('\t'); '\\' -> decoded.append('\\'); '"' -> decoded.append('"'); else -> valid = false
                        }; i += 2
                    } else if (text[i] == '\\') i++ else decoded.append(text[i++])
                }
                if (!closed) {
                    kind = "invalid"; value = "unterminated string"
                } else if (!valid) {
                    kind = "invalid"; value = "invalid escape sequence"
                } else {
                    kind = "string"; value = decoded.toString()
                }
            } else {
                if (i + 1 < text.length && text.substring(i, i + 2) in listOf(";;", "->", "::", "||", "&&", "<=", ">=", "<>")) {
                    i += 2; kind = "symbol"; value = text.substring(start, i)
                }
                else if (text[i] in ":;=<>+-*/^()[],|") {
                    i++; kind = "symbol"; value = text.substring(start, i)
                }
                else {
                    kind = "invalid"; value = "illegal character '${text[i++]}'"
                }
            }
            tokens.add(Token(kind, text.substring(start, i), value, positions[start]))
        }
        tokens.add(Token("eof", "", "", positions.last())); return tokens
    }
}

import java.io.File
fun quote(value: String): String = "\"" + buildString {
    for (c in value) append(when (c) {
        '\\' -> "\\\\"; '"' -> "\\\""; '\n' -> "\\n"; '\t' -> "\\t"; else -> c.toString()
    })
} + "\""
fun valueString(value: Value): String = when (value) {
    is Value.Integer -> value.value.toString()
    is Value.BooleanValue -> value.value.toString()
    is Value.StringValue -> quote(value.value)
    is Value.PairValue -> "(${valueString(value.first)}, ${valueString(value.second)})"
    is Value.ListValue -> value.values.joinToString("; ", "[", "]") {
        valueString(it)
    }
    else -> "<fun>"
}
fun editDistance(a: String, b: String): Int {
    var row = (0..b.length).toList()
    for ((i, x) in a.withIndex()) {
        val next = mutableListOf(i + 1); for ((j, y) in b.withIndex()) next.add(minOf(next[j] + 1, row[j + 1] + 1, row[j] + if (x == y) 0 else 1)); row = next
    }; return row[b.length]
}
class TypePrinter(val unifier: Unifier, val quantified: Set<Int>? = null) {
    val names = mutableMapOf<Int, String>()
    fun write(type: MLType): String = when (val t = unifier.resolve(type)) {
        MLType.IntType -> "int"
        MLType.BoolType -> "bool"
        MLType.StringType -> "string"
        is MLType.Variable -> names.getOrPut(t.id) {
            val k = names.size; "'" + (if (quantified != null && t.id !in quantified) "_" else "") + ('a'.code + k % 26).toChar() + if (k >= 26) (k / 26).toString() else ""
        }
        is MLType.ListType -> wrap(t.element, true) + " list"
        is MLType.PairType -> wrap(t.first, true) + " * " + wrap(t.second, true)
        is MLType.Function -> wrap(t.argument, false) + " -> " + write(t.result)
    }
    fun wrap(type: MLType, pair: Boolean): String {
        val t = unifier.resolve(type); val text = write(t); return if (t is MLType.Function || pair && t is MLType.PairType) "($text)" else text
    }
}
fun errorMessage(error: TypeError, unifier: Unifier): String {
    val printer = TypePrinter(unifier)
    return when (val kind = error.kind) {
        is TypeErrorKind.Message -> kind.text
        is TypeErrorKind.Function -> "expected a function but found ${printer.write(kind.type)}"
        is TypeErrorKind.Check -> {
            var message = "expected ${printer.write(kind.expected)} but found ${printer.write(kind.found)}"
            val failure = kind.failure
            if (failure.occurs) {
                val variable = if (failure.expected is MLType.Variable) failure.expected else failure.found; val other = if (failure.expected is MLType.Variable) failure.found else failure.expected; message += " (infinite type ${printer.write(variable)} = ${printer.write(other)})"
            }
            else if (failure.nested) message += " (${printer.write(failure.expected)} vs ${printer.write(failure.found)})"
            message
        }
    }
}
fun signatureType(type: TypeExpression, unifier: Unifier, variables: MutableMap<String, MLType>): MLType = when (type) {
    is TypeExpression.Primitive -> when (type.name) {
        "int" -> MLType.IntType; "bool" -> MLType.BoolType; else -> MLType.StringType
    }
    is TypeExpression.Variable -> variables.getOrPut(type.name) {
        unifier.fresh()
    }
    is TypeExpression.ListType -> MLType.ListType(signatureType(type.element, unifier, variables))
    is TypeExpression.PairType -> MLType.PairType(signatureType(type.first, unifier, variables), signatureType(type.second, unifier, variables))
    is TypeExpression.Function -> MLType.Function(signatureType(type.argument, unifier, variables), signatureType(type.result, unifier, variables))
}
fun signatureMatches(inferred: MLType, declared: MLType, unifier: Unifier, assigned: MutableMap<Int, MLType>): Boolean {
    val a = unifier.resolve(inferred); val b = unifier.resolve(declared)
    if (a is MLType.Variable) {
        val old = assigned[a.id]; if (old != null) return old == b; assigned[a.id] = b; return true
    }
    return when {
        a is MLType.ListType && b is MLType.ListType -> signatureMatches(a.element, b.element, unifier, assigned)
        a is MLType.PairType && b is MLType.PairType -> signatureMatches(a.first, b.first, unifier, assigned) && signatureMatches(a.second, b.second, unifier, assigned)
        a is MLType.Function && b is MLType.Function -> signatureMatches(a.argument, b.argument, unifier, assigned) && signatureMatches(a.result, b.result, unifier, assigned)
        else -> a == b
    }
}
fun typeSyntax(type: TypeExpression): String {
    fun wrap(t: TypeExpression, pair: Boolean): String {
        val text = typeSyntax(t); return if (t is TypeExpression.Function || pair && t is TypeExpression.PairType) "($text)" else text
    }
    return when (type) {
        is TypeExpression.Primitive -> type.name; is TypeExpression.Variable -> type.name; is TypeExpression.ListType -> wrap(type.element, true) + " list"; is TypeExpression.PairType -> wrap(type.first, true) + " * " + wrap(type.second, true); is TypeExpression.Function -> wrap(type.argument, false) + " -> " + typeSyntax(type.result)
    }
}
fun patternString(p: Pattern): String = when (p) {
    is WildPattern -> "_"
    is NamePattern -> p.name
    is IntPattern -> p.value.toString()
    is BoolPattern -> p.value.toString()
    is StringPattern -> quote(p.value)
    is ListPattern -> p.elements.joinToString("; ", "[", "]") {
        patternString(it)
    }
    is PairPattern -> "(${patternString(p.first)}, ${patternString(p.second)})"
    is ConsPattern -> (if (p.head is ConsPattern) "(${patternString(p.head)})" else patternString(p.head)) + " :: " + patternString(p.tail)
}
fun groupString(group: Group): String = "let " + (if (group.recursive != null) "rec " else "") + group.bindings.joinToString(" and ") {
    binding -> var body = binding.expression; val names = mutableListOf(binding.name); while (body is Lambda) {
        names.add(body.parameter.name ?: "_"); body = body.body
    }; names.joinToString(" ") + " = " + expressionString(body, 0)
}
fun endsInMatch(e: Expr): Boolean = when (e) {
    is Match -> true; is LetIn -> endsInMatch(e.body); is Lambda -> endsInMatch(e.body); is Conditional -> endsInMatch(e.no); else -> false
}
fun expressionString(e: Expr, required: Int): String {
    val strength: Int; val text: String
    when (e) {
        is IntExpr -> {
            strength = 9; text = e.value.toString()
        }
        is BoolExpr -> {
            strength = 9; text = e.value.toString()
        }
        is StringExpr -> {
            strength = 9; text = quote(e.value)
        }
        is NameExpr -> {
            strength = 9; text = e.name
        }
        is Lambda -> {
            var body: Expr = e; val names = mutableListOf<String>(); while (body is Lambda) {
                names.add(body.parameter.name ?: "_"); body = body.body
            }; strength = 0; text = "fun " + names.joinToString(" ") + " -> " + expressionString(body, 0)
        }
        is Apply -> {
            strength = 8; text = expressionString(e.function, 8) + " " + expressionString(e.argument, 9)
        }
        is Binary -> {
            val k = precedence(e.op); val right = rightAssociative(e.op); strength = k; text = expressionString(e.left, k + if (right) 1 else 0) + " " + e.op + " " + expressionString(e.right, k + if (right) 0 else 1)
        }
        is Negate -> {
            strength = 7; text = "-" + expressionString(e.operand, 7)
        }
        is Conditional -> {
            strength = 0; text = "if ${expressionString(e.condition, 0)} then ${expressionString(e.yes, 0)} else ${expressionString(e.no, 0)}"
        }
        is PairExpr -> {
            strength = 9; text = "(${expressionString(e.first, 0)}, ${expressionString(e.second, 0)})"
        }
        is ListExpr -> {
